    h, w = len(grid), len(grid[0])
    # Recover the smaller pattern by observing the unique colors over the
    # repeated background lattice. Reducing every other lattice junction
    # preserves the spacing of the encoded grid.
    nr, nc = (h - 1) // 7, (w - 1) // 7
    out = [[9] * nc for _ in range(nr)]
    for i in range(nr):
        for j in range(nc):
            r, c = 7 * (i + 1), 7 * (j + 1)
            if r < h and c < w:
                v = grid[r][c]
                if v not in (1, 3, 9):
                    out[i][j] = v
    return out
