 "content": "from collections import Counter


def _majority_lines(grid, color, axis, threshold=0.72):
    h, w = len(grid), len(grid[0])
    n, m = (h, w) if axis == 0 else (w, h)
    coords = []
    for i in range(n):
        count = sum((grid[i][j] if axis == 0 else grid[j][i]) == color
                    for j in range(m))
        if count / m >= threshold:
            coords.append(i)
    return coords


def _period(coords):
    gaps = [b - a for a, b in zip(coords, coords[1:])]
    if not gaps:
        return None, 0.0
    gap, count = Counter(gaps).most_common(1)[0]
    return (gap, count / len(gaps))


def transform(grid):
    h, w = len(grid), len(grid[0])
    best = None
    # A structural line color repeats at regularly spaced rows AND columns;
    # the cell fill tends to form contiguous runs instead.
    for color in range(10):
        rs = _majority_lines(grid, color, 0)
        cs = _majority_lines(grid, color, 1)
        rp, rregular = _period(rs)
        cp, cregular = _period(cs)
        if not rp or not cp or rp <= 1 or cp <= 1:
            continue
        score = len(rs) + len(cs) + 4 * (rregular + cregular)
        if best is None or score > best[0]:
            best = (score, color, rs, cs)
    if best is None:
        return [row[:] for row in grid]
    _, line, rows, cols = best

    # Any non-line, non-fill intersection is a colored marker. Find the
    # minimal lattice rectangle containing all such markers.
    interior_values = []
    for r0, r1 in zip(rows, rows[1:]):
        for c0, c1 in zip(cols, cols[1:]):
            interior_values.extend(grid[r][c] for r in range(r0 + 1, r1)
                                   for c in range(c0 + 1, c1))
    fill = Counter(interior_values).most_common(1)[0][0] if interior_values else line
    markers = [(r, c) for r in rows for c in cols
               if grid[r][c] != line and grid[r][c] != fill]
    if not markers:
        return []
    rmin, rmax = min(r for r, _ in markers), max(r for r, _ in markers)
    cmin, cmax = min(c for _, c in markers), max(c for _, c in markers)
    rows = [r for r in rows if rmin <= r <= rmax]
    cols = [c for c in cols if cmin <= c <= cmax]

    out = []
    for i in range(len(rows) - 1):
        out_row = []
        for j in range(len(cols) - 1):
            corners = (grid[rows[i]][cols[j]], grid[rows[i]][cols[j + 1]],
                       grid[rows[i + 1]][cols[j]], grid[rows[i + 1]][cols[j + 1]])
            color = corners[0]
            if color != line and color != fill and all(v == color for v in corners):
                out_row.append(color)
            else:
                out_row.append(fill)
        out.append(out_row)
    return out
