from math import gcd


def _majority_color(grid, axis, threshold=0.80):
    h,w=len(grid),len(grid[0]); n,m=(h,w) if axis==0 else (w,h)
    scores=Counter()
    for i in range(n):
        vals=[grid[i][j] if axis==0 else grid[j][i] for j in range(m)]
        color,count=Counter(vals).most_common(1)[0]
        if count/m>=threshold:
            scores[color]+=1
    return scores.most_common(1)[0][0] if scores else None


def _period(coords):
    gaps=[b-a for a,b in zip(coords,coords[1:])]
    p=0
    for d in gaps: p=gcd(p,d)
    return p


def transform(grid):
    h,w=len(grid),len(grid[0])
    # Determine grid-line colors from long, mostly uniform rows and columns.
    lc1=_majority_color(grid,0); lc2=_majority_color(grid,1)
    line=lc1 if lc1 is not None else lc2
    if line is None: return [row[:] for row in grid]
    def detect(axis):
        n,m=(h,w) if axis==0 else (w,h)
        coords=[]
        for i in range(n):
            vals=[grid[i][j] if axis==0 else grid[j][i] for j in range(m)]
            if sum(v==line for v in vals)>=m*0.80: coords.append(i)
        p=_period(coords)
        if p<2:
            # Use dominant periodic color runs to infer pitch from dimensions.
            candidates=[d for d in range(2,n) if (n-1)%d==0]
            for d in candidates:
                if all(any(abs(x-(k*d))<=0 for x in coords) for k in range(0,n//d+1)):
                    p=d; break
        if p<2: return coords
        start=coords[0] if coords else 0
        return list(range(start,n,p))
    rows,cols=detect(0),detect(1)
    if len(rows)<2 or len(cols)<2: return [row[:] for row in grid]

    # Find the common interior fill color in a typical open rectangle.
    interiors=[]
    for r0,r1 in zip(rows,rows[1:]):
        for c0,c1 in zip(cols,cols[1:]):
            interiors.extend(grid[r][c] for r in range(r0+1,r1)
                             for c in range(c0+1,c1))
    fill=Counter(interiors).most_common(1)[0][0] if interiors else 0
    # Each repeated crossing is an output pixel, retaining its marker color;
    # crop to rows/columns that contain non-line marker intersections.
    marked=[(i,j) for i,r in enumerate(rows) for j,c in enumerate(cols)
            if grid[r][c] not in (line,fill)]
    if not marked: return []
    ri=[i for i in range(len(rows)) if min(a for a,_ in marked)<=i<=max(a for a,_ in marked)]
    cj=[j for j in range(len(cols)) if min(b for _,b in marked)<=j<=max(b for _,b in marked)]
    return [[grid[rows[i]][cols[j]] if grid[rows[i]][cols[j]] not in (line,fill) else fill
             for j in cj] for i in ri]
