            vals=[grid[i][j] if axis==0 else grid[j][i] for j in range(m)]
            color,count=Counter(vals).most_common(1)[0]
            if count/m>=.75: rows.append((i,color))
        # Use the most frequent color among long lines on this axis.
        line=Counter(c for _,c in rows).most_common(1)[0][0]
        coords=[i for i,c in rows if c==line]
        return line,_compress_runs(coords)
    lr,rs=axis_lines(0); lc,cs=axis_lines(1)
    # The matrix of intersections between long horizontal and vertical stripes
