 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    freq = Counter(v for row in grid for v in row)
    line = freq.most_common(1)[0][0]
    # Full line positions are visible as rows/columns dominated by the lattice color.
    rs = [r for r in range(h) if sum(x == line for x in grid[r]) >= w * .8]
    cs = [c for c in range(w) if sum(grid[r][c] == line for r in range(h)) >= h * .8]
    def pack(xs):
        groups=[]
        for x in xs:
            if not groups or x > groups[-1][-1] + 1: groups.append([x])
            else: groups[-1].append(x)
        return [g[len(g)//2] for g in groups]
    rs,cs=pack(rs),pack(cs)
    if len(rs)<2 or len(cs)<2:return []
    # At each crossing, non-line colors are the encoded values; ordinary
    # crossings become the interior/background color.
    interior=[grid[r][c] for r in range(h) for c in range(w) if r not in rs and c not in cs]
    blank=Counter(interior).most_common(1)[0][0] if interior else 9
    values=[[grid[r][c] for c in cs] for r in rs]
    # Output cell receives the marker only when the four corners agree;
    # otherwise it is blank. This rule reproduces the demonstrations.
    out=[]
    for i in range(len(rs)-1):
        out.append([values[i][j] if values[i][j]==values[i+1][j]==values[i][j+1]==values[i+1][j+1] else blank
                    for j in range(len(cs)-1)])
    return out
