def transform(grid):
    h,w=len(grid),len(grid[0])
    freq=Counter(v for row in grid for v in row)
    line=freq.most_common(1)[0][0]
    # Long, nearly uniform rows and columns reveal horizontal/vertical
    # grid-line bands. A marker may replace the line color at a crossing.
    def stripes(axis):
        n,m=(h,w) if axis==0 else (w,h)
        xs=[]
        for i in range(n):
            vals=[grid[i][j] if axis==0 else grid[j][i] for j in range(m)]
            if sum(v==line for v in vals)>=m-3:xs.append(i)
        groups=[]
        for x in xs:
            if not groups or x>groups[-1][-1]+1:groups.append([x])
            else:groups[-1].append(x)
        return [g[len(g)//2] for g in groups]
    rows,cols=stripes(0),stripes(1)
    if len(rows)<2 or len(cols)<2:return []
    # Marked grid intersections represent output cells; blank is color 9.
    out=[]
    for r in rows:
        out.append([grid[r][c] if grid[r][c]!=line else 9 for c in cols])
    # Drop outer margin only if it is entirely blank.
    while out and all(v==9 for v in out[0]):out=out[1:]
    while out and all(v==9 for v in out[-1]):out=out[:-1]
    if out:
        while all(row[0]==9 for row in out):out=[row[1:] for row in out]
        while all(row[-1]==9 for row in out):out=[row[:-1] for row in out]
    return out
