 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = set(v for row in grid for v in row)

    # A lattice color forms thin, regularly spaced full-width and full-height
    # stripes. Prefer the color whose qualifying stripes form the thinnest bands.
    candidates = []
    for color in colors:
        row_ids = [r for r in range(h) if sum(v == color for v in grid[r]) >= 0.80 * w]
        col_ids = [c for c in range(w) if sum(grid[r][c] == color for r in range(h)) >= 0.80 * h]

        def groups(ids):
            result = []
            for x in ids:
                if not result or x > result[-1][-1] + 1:
                    result.append([x])
                else:
                    result[-1].append(x)
            return result

        rg, cg = groups(row_ids), groups(col_ids)
        if len(rg) >= 2 and len(cg) >= 2:
            thinness = (sum(map(len, rg)) / len(rg) + sum(map(len, cg)) / len(cg))
            candidates.append((thinness, color, rg, cg))
    if not candidates:
        return [row[:] for row in grid]
    _, line, row_groups, col_groups = min(candidates, key=lambda x: x[0])
    rows = [g[len(g) // 2] for g in row_groups]
    cols = [g[len(g) // 2] for g in col_groups]

    # Blank is the modal color away from the stripe bands.
    row_band = {r for g in row_groups for r in g}
    col_band = {c for g in col_groups for c in g}
    interior = [grid[r][c] for r in range(h) for c in range(w)
                if r not in row_band and c not in col_band]
    blank = Counter(interior).most_common(1)[0][0] if interior else line

    # The reduced picture takes every second crossing. Start at the first
    # horizontal/vertical stripe that contains a non-structural marker.
    row_start = next((i for i, r in enumerate(rows)
                      if any(grid[r][c] != line for c in cols)), 0)
    col_start = next((j for j, c in enumerate(cols)
                      if any(grid[r][c] != line for r in rows)), 0)
    sample_rows = rows[row_start::2]
    sample_cols = cols[col_start::2]
    out = [[grid[r][c] if grid[r][c] != line else blank for c in sample_cols]
           for r in sample_rows]

    # Remove blank-only outer rows and columns, as in the demonstrations.
    while out and all(v == blank for v in out[0]):
        out.pop(0)
    while out and all(v == blank for v in out[-1]):
        out.pop()
    while out and all(row[0] == blank for row in out):
        out = [row[1:] for row in out]
    while out and all(row[-1] == blank for row in out):
        out = [row[:-1] for row in out]
    return out
